const pages = Array.isArray($json.results) ? $json.results : [];
const text = (property) => {
  if (!property) return '';
  if (property.type === 'title') return (property.title || []).map(v => v.plain_text || '').join('');
  if (property.type === 'rich_text') return (property.rich_text || []).map(v => v.plain_text || '').join('');
  if (property.type === 'email') return property.email || '';
  if (property.type === 'url') return property.url || '';
  if (property.type === 'phone_number') return property.phone_number || '';
  if (property.type === 'select') return property.select?.name || '';
  return '';
};
return pages.map(page => {
  const p = page.properties || {};
  const selectedPackages = (p['Leistungspakete']?.multi_select || []).map(option => {
    const name = option.name;
    if (name === 'Handwerker Landingpage') return { id: 'landingpage', price: p['Preis Landingpage']?.number || 0 };
    if (name === 'Lead-System') return { id: 'lead-system', price: p['Preis Lead-System']?.number || 0 };
    if (name === 'Automation & Betreuung') return { id: 'automation', price: p['Preis Automation']?.number || 0 };
    return null;
  }).filter(Boolean);
  const tier = p['Monatliche Betreuung']?.select?.name || '';
  return { json: { notionPageId: page.id, leadId: text(p['Lead ID']), company: text(p['Firma / Name']), name: text(p['Ansprechpartner']), email: text(p['E-Mail']), website: text(p['Website']), projectDescription: text(p['Anliegen']) + (text(p['Nachricht']) ? '\n' + text(p['Nachricht']) : ''), selectedPackages, monthlyCare: tier ? { tier, price: p['Preis Betreuung']?.number || 0 } : null, notes: text(p['Notizen']) } };
});

const input = $json;
const packages = {
  'landingpage': { title: 'Handwerker Landingpage', min: 900, max: 1500, items: ['Moderne Landingpage','Mobile Optimierung','Kontaktformular','DSGVO-orientierte Formularstruktur','Basis-SEO','Technische Einrichtung'] },
  'lead-system': { title: 'Lead-System', min: 800, max: 1500, items: ['Formularanbindung','n8n Webhook','CRM-Speicherung','Interne Benachrichtigung','Eingangsbestätigung','Lead-Statusverwaltung'] },
  'automation': { title: 'Automation & Betreuung', min: 1500, max: 3000, items: ['Individuelle Prozessautomationen','Follow-up-Erinnerungen','Anfrageverwaltung','Optimierung bestehender Abläufe','Monatliche Betreuung möglich'] }
};
const chosen = Array.isArray(input.selectedPackages) ? input.selectedPackages : [];
const errors = [];
const normalized = chosen.map(entry => {
  const id = String(entry.id || '');
  const definition = packages[id];
  const price = Number(entry.price || 0);
  if (!definition) { errors.push(`Unbekanntes Paket: ${id}`); return null; }
  if (price < definition.min || price > definition.max) errors.push(`${definition.title}: Preis muss zwischen ${definition.min} und ${definition.max} EUR liegen.`);
  return { id, ...definition, price };
}).filter(Boolean);
if (!normalized.length) errors.push('Mindestens ein Leistungspaket muss ausgewählt und bepreist werden.');
let monthlyCare = null;
if (input.monthlyCare?.tier) {
  const tier = String(input.monthlyCare.tier);
  const price = Number(input.monthlyCare.price || 0);
  const valid = tier === 'Basic' ? price >= 49 && price <= 99 : tier === 'Standard' ? price === 149 : tier === 'Premium' ? price >= 249 && price <= 299 : false;
  if (!valid) errors.push('Preis der monatlichen Betreuung liegt außerhalb des vorgesehenen Bereichs.');
  monthlyCare = { tier, price };
}
const now = new Date();
const date = now.toISOString().slice(0, 10);
const validUntil = new Date(now.getTime() + 14 * 86400000).toISOString().slice(0, 10);
const suffix = String(input.leadId || Date.now().toString(36)).replace(/[^a-z0-9]/gi, '').slice(-8).toUpperCase();
const offerNumber = `NW-ANG-${date.replace(/-/g, '')}-${suffix}`;
const total = normalized.reduce((sum, entry) => sum + entry.price, 0);
return [{ json: { ...input, ready: errors.length === 0, errors, packages: normalized, monthlyCare, offerNumber, offerDate: date, validUntil, total, paymentTerms: '50 % Anzahlung bei Projektstart, 50 % nach Fertigstellung', nextStep: 'Angebot intern prüfen, freigeben und anschließend manuell versenden.' } }];

const d = $json;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = value => new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(value);
const packageHtml = d.packages.map(entry => `<section class="package"><div class="package-head"><h2>${esc(entry.title)}</h2><strong>${money(entry.price)}</strong></div><ul>${entry.items.map(item => `<li>${esc(item)}</li>`).join('')}</ul></section>`).join('');
const careHtml = d.monthlyCare ? `<section class="care"><h2>Monatliche Betreuung</h2><p>${esc(d.monthlyCare.tier)} · ${money(d.monthlyCare.price)} pro Monat</p></section>` : '';
const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Angebot ${esc(d.offerNumber)}</title><style>body{font-family:Arial,sans-serif;color:#0b2545;margin:0;background:#f5f7fa}main{max-width:820px;margin:32px auto;background:white;padding:54px}header{border-bottom:4px solid #1976d2;padding-bottom:24px;margin-bottom:34px}.brand{font-size:28px;font-weight:800}.brand small{display:block;color:#60758a;font-size:12px;letter-spacing:.08em;margin-top:5px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:28px 0}.box,.package,.care{border:1px solid #dce5ec;border-radius:10px;padding:20px;margin:16px 0}.package-head{display:flex;justify-content:space-between;gap:20px}.package h2,.care h2{font-size:18px;margin:0 0 12px}.package-head strong{color:#0866c6}li{margin:7px 0}.total{font-size:22px;font-weight:800;text-align:right;margin:28px 0}.fine{color:#526779;font-size:13px;line-height:1.6}footer{border-top:1px solid #dce5ec;margin-top:40px;padding-top:20px;color:#60758a;font-size:12px}@media print{body{background:#fff}main{margin:0;max-width:none}}</style></head><body><main><header><div class="brand">NOVAWERK<small>DIGITALE SYSTEME FÜR HANDWERKSBETRIEBE</small></div></header><h1>Angebot</h1><div class="meta"><div><strong>Angebotsnummer</strong><br>${esc(d.offerNumber)}</div><div><strong>Datum</strong><br>${esc(d.offerDate)}</div><div><strong>Kunde</strong><br>${esc(d.company || d.name)}</div><div><strong>Gültig bis</strong><br>${esc(d.validUntil)}</div></div><section class="box"><h2>Projektbeschreibung</h2><p>${esc(d.projectDescription || 'Projektumfang gemäß Abstimmung.')}</p></section>${packageHtml}${careHtml}<div class="total">Projektpreis: ${money(d.total)}</div><section class="box fine"><strong>Zahlungsbedingungen</strong><p>${esc(d.paymentTerms)}</p><strong>Nächster Schritt</strong><p>${esc(d.nextStep)}</p></section><footer>NOVAWERK · Digitale Systeme für Handwerksbetriebe<br>Interner Angebotsentwurf – vor Versand manuell prüfen.</footer></main></body></html>`;
const summary = [`Angebot ${d.offerNumber}`, ...d.packages.map(p => `${p.title}: ${money(p.price)}`), `Gesamt: ${money(d.total)}`, d.monthlyCare ? `Betreuung: ${d.monthlyCare.tier} ${money(d.monthlyCare.price)}/Monat` : '', `Gültig bis: ${d.validUntil}`, d.paymentTerms].filter(Boolean).join('\n');
return [{ json: { ...d, offerSummary: summary, fileName: `${d.offerNumber}.html`, mimeType: 'text/html' }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: `${d.offerNumber}.html`, fileExtension: 'html' } } }];

const draft = $('NOVAWERK Angebotsentwurf erstellen').item.json;
const notion = $json ?? {};
const notionUpdated = Boolean(notion.id) && !notion.error;
return [{ json: { success: true, draftOnly: true, sent: false, offerNumber: draft.offerNumber, total: draft.total, validUntil: draft.validUntil, notionUpdated, notionPageId: notion.id || draft.notionPageId || '', fileName: draft.fileName, report: notionUpdated ? 'Angebotsentwurf erstellt und im CRM vermerkt. Keine E-Mail versendet.' : 'Angebotsentwurf erstellt; CRM-Aktualisierung muss geprüft werden. Keine E-Mail versendet.' }, binary: $('NOVAWERK Angebotsentwurf erstellen').item.binary }];
